-- create the project table sequence
CREATE SEQUENCE
  gs.seq_project
AS
  integer
OWNED BY
  gs.project.id;

-- offset the next id to be generated by a margin from migrated projects
SELECT
  setval('gs.seq_project', (SELECT 1000 + max("ID") FROM staging."Projects"));

-- wire the sequence into the id column
ALTER TABLE gs.project
ALTER COLUMN id SET DEFAULT nextval('gs.seq_project');